{
  "title": "Asynchronous Processing and Background Task Management",
  "description": "This documentation report details the comprehensive asynchronous processing architecture of the merged software cluster, leveraging a dual strategy for event-driven interactions and background task execution. The system integrates message-driven consumers for real-time event handling via RabbitMQ and robust background job processors, Delayed Job and Sidekiq, for deferred and scheduled tasks. This setup ensures efficient, scalable, and resilient task management across various microservices.",
  "functional_domain": "Asynchronous Task Execution and Background Processing",
  "architecture_overview": "The application employs a dual strategy for asynchronous processing: message-driven consumers for real-time event handling via RabbitMQ and background jobs for deferred and scheduled tasks using Delayed Job and Sidekiq. This architecture provides clear separation of concerns, enabling efficient inter-service communication and robust task execution.",
  "components": [
    {
      "name": "Message Consumers (Msgr)",
      "description": "Inter-service communication and event processing are handled by `Msgr::Consumer` classes, which subscribe to RabbitMQ queues. Each consumer defines methods corresponding to specific message routes or event types, processing the message `payload` and acknowledging the message (`message.ack`) to prevent re-delivery.",
      "sub_components": [
        {
          "name": "GamificationConsumer",
          "details": "Processes gamification-related events, checking `Xikolo.config.gamification['enabled']` before processing. It dispatches to specific `Gamification::Rules` based on `exercise_type` (e.g., `main`, `selftest` for `result_create`) or `votable_type` (e.g., `Answer`, `Question` for `vote_create`). It also handles events for visiting items, creating comments, creating questions, accepting answers, and creating answers."
        },
        {
          "name": "CourseConsumer",
          "details": "Handles course-related events, specifically the `clone` event. Upon receiving a `clone` message with `old_course_id` and `new_course_code`, it delegates the cloning logic to `Course::Clone.call`."
        },
        {
          "name": "NewsConsumer",
          "details": "Processes `update_state` messages, typically from the notification service. It extracts a `news_id` (UUID) and other payload data to update the corresponding `News` record."
        }
      ],
      "key_features": [
        "Real-time event handling",
        "Inter-service communication",
        "Message acknowledgment",
        "Event-driven interactions"
      ]
    },
    {
      "name": "Background Jobs (Delayed Job)",
      "description": "The main application utilizes `delayed_job` for asynchronous task execution. Jobs inherit from `ApplicationJob` and can specify their queue, maximum attempts, and maximum run time. The `Delayed::Worker` manages the execution of these jobs.",
      "sub_components": [
        {
          "name": "Configuration",
          "details": "`config/initializers/delayed.rb` sets global `Delayed::Worker` parameters, restricting work to specific queues (`default`, `long_running`, `mails`), setting a global `max_attempts` to 25, and a `max_run_time` of 10 hours. It integrates with `ActiveSupport::Notifications` to publish metrics about delayed jobs to `Xikolo.metrics`."
        },
        {
          "name": "LongRunningApplicationJob",
          "details": "A base class for jobs expected to run for extended periods. It sets its queue to `'long_running'` and explicitly defines `max_run_time` to 10 hours and `max_attempts` to 5."
        },
        {
          "name": "Lti::PublishGradeJob",
          "details": "Publishes a user's LTI grade to the course service, contributing to course progress. Operates on the `default` queue and calls the `publish!` method of an `Lti::Grade` record."
        },
        {
          "name": "Proctoring::StoreSubmissionResultsJob",
          "details": "Loads proctoring results for a quiz from an external vendor and stores them in the submission's vendor data attribute. Triggered after learners submit proctored quizzes, it uses the `default` queue with an `eventual` priority and includes robust retry logic for `Proctoring::ServiceError` (up to 10 attempts) and `ExpectedRetry` (48 attempts)."
        },
        {
          "name": "Proctoring::UploadCertificateImageJob",
          "details": "Fetches a user's proctoring image from SMOWL and uploads it to S3 for certificate printing. Runs on the `default` queue with `eventual` priority and includes retry logic for `Proctoring::ServiceError`."
        },
        {
          "name": "RefreshSitemapJob",
          "details": "A deprecated job that performs no action but is retained to allow any pending jobs to complete."
        }
      ],
      "key_features": [
        "Deferred tasks",
        "Configurable job queues",
        "Global and job-specific retry logic",
        "Metrics integration",
        "Long-running task support"
      ]
    },
    {
      "name": "Background Jobs (Sidekiq)",
      "description": "Sidekiq is utilized for scheduled tasks, with `sidekiq-cron` managing cron job definitions. The `xikolo-sidekiq` gem centralizes Sidekiq setup and configuration, including Redis connection settings and cron job loading. Sidekiq jobs are `ActiveJob` compatible.",
      "sub_components": [
        {
          "name": "Redis Configuration",
          "details": "Each service (main app, account, course, news, notification, pinboard, quiz, timeeffort) has a `config/sidekiq_redis.yml` file. These files define common Redis connection settings and specify different Redis databases (`db`) for each environment (development, test, integration, production) to isolate data."
        },
        {
          "name": "Cron Jobs",
          "details": "`config/cron.yml` files define recurring tasks across services. The main application schedules `Voucher::DeleteClaimantIPJob` (daily at 4:15 a.m.) and `Video::SyncVideosJob` (every 2 hours). The Account Service schedules `UnconfirmedAccountsDeletionWorker` (daily at 3 a.m.) to delete old, unconfirmed accounts."
        }
      ],
      "key_features": [
        "Scheduled tasks",
        "Cron job definitions",
        "Redis database isolation for services",
        "Centralized Sidekiq configuration via `xikolo-sidekiq`",
        "ActiveJob compatibility"
      ]
    }
  ],
  "overall_summary": "This robust asynchronous processing architecture effectively leverages the strengths of both message queues for real-time, event-driven interactions and background job processors for deferred and scheduled tasks. With clear separation of concerns across microservices, centralized Sidekiq configuration via the `xikolo-sidekiq` gem, and comprehensive retry and monitoring capabilities, the system ensures reliable and scalable task execution for a wide range of application functionalities."
}
